import{_ as e,c as s,o,ah as n}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"AI assistant","description":"","frontmatter":{"title":"AI assistant"},"headers":[],"relativePath":"ai/general.md","filePath":"ai/general.md"}'),a={name:"ai/general.md"};function r(i,t,h,d,l,g){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-assistant" tabindex="-1">AI assistant <a class="header-anchor" href="#ai-assistant" aria-label="Permalink to &quot;AI assistant&quot;">​</a></h1><p>The <strong>AI assistant</strong> tab sits after <strong>Logs</strong>. The header on the tab says <strong>AI</strong>. The assistant answers questions about the captured logs and the page. Attaching a request, a component, a store or a log event is described on those tabs.</p><p>Connection, what the assistant may read, masking, style and the model list are in <a href="/qa-tools/docs/ai/settings.html">Options → AI</a>. This page is the chat itself.</p><h2 id="before-the-first-question" tabindex="-1">Before the first question <a class="header-anchor" href="#before-the-first-question" aria-label="Permalink to &quot;Before the first question&quot;">​</a></h2><p>With no API key the tab says <strong>Connect an AI provider</strong> and offers <strong>Connect in Options → AI</strong>. The text names a free key of Gemini or OpenRouter.</p><p>With a key but no confirmation, the tab says <strong>Data sent to OpenRouter</strong> or <strong>Data sent to Gemini</strong>:</p><ul><li>questions, a digest of the captured logs, the event data and the page code the assistant asks for;</li><li>tokens, passwords, API keys and other values from the AI masking list are replaced with <code>[MASKED]</code> before sending; what the assistant may read is set in <strong>Options → AI → Agent access</strong>;</li><li>free models may store prompts and use them for training.</li></ul><p><strong>I understand</strong> confirms. <strong>Review access</strong> opens <strong>Options → AI → Agent access</strong>. Until then the input stays disabled and reads <strong>Connect a provider to ask questions</strong>.</p><p>After confirmation, an empty chat offers four example questions. Clicking one sends it.</p><h2 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Behavior</th></tr></thead><tbody><tr><td>Provider</td><td><strong>OpenRouter</strong> or <strong>Gemini</strong></td></tr><tr><td>Model</td><td>Shown when a key is set and the model list has loaded. <strong>Auto</strong> is first: <em>free models, switches on limits</em>. Then <strong>Recommended</strong> and <strong>Added</strong>. A model note can say <strong>paid</strong>, a status, <strong>unstable</strong>, and how many requests it had today</td></tr><tr><td><strong>Checking models...</strong></td><td>Shown while the list loads</td></tr><tr><td><strong>Models failed to load, retry</strong></td><td>Shown when the list fails. The title is the error text</td></tr><tr><td>Refresh</td><td>Tooltip <strong>Check which models are available</strong></td></tr><tr><td>Settings</td><td>Tooltip <strong>AI settings: connection, access, masking, style, models</strong>. Opens <strong>Options → AI</strong></td></tr><tr><td><strong>New chat</strong></td><td>Tooltip <strong>New chat</strong>. Disabled when the chat is empty and the assistant is idle. Clears the conversation. The conversation stays while the inspector is open, including after switching tabs. Reloading the page starts an empty chat</td></tr></tbody></table><p>The model list is hidden until a key exists and models have loaded.</p><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><p>The placeholder is <strong>Ask AI</strong>. With chips attached it is <strong>Ask about the attached data</strong>.</p><p><strong>Enter</strong> sends. <strong>Shift+Enter</strong> inserts a line. The send button tooltip is <strong>Send (Enter; Shift+Enter for a new line)</strong>. Send needs text or at least one chip. Sending only chips asks the assistant to explain the attached data and point out anything wrong in it. The chip stays on the question; <strong>×</strong> removes it before sending.</p><p>While an answer is running the button is <strong>Stop</strong>.</p><p>Under the field, when the chat is ready:</p><ul><li>OpenRouter: <strong>Today: N of M free OpenRouter requests (counted in this browser). Each assistant step is one request.</strong> <strong>M</strong> is the limit the provider reported, or <strong>50</strong> when it has not. In <strong>Auto</strong>, a second sentence says how many models are skipped because they are out of quota or unavailable.</li><li>Gemini: <strong>Today: N Gemini requests. Daily limits depend on the model and your Google AI Studio project.</strong> The same <strong>Auto</strong> sentence can follow.</li></ul><p><strong>Auto</strong> can be selected only when the list has a model that is not marked paid. A hand-picked model must be selected for the field to accept a question.</p><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><p>The question is on the right. The answer is on the left, with the model name and the request count for that answer.</p><p><strong>Copy</strong> on a message copies its text. The tooltip becomes <strong>Copied</strong>, or a toast says <strong>Could not copy to the clipboard</strong>. A code block in the answer has its own copy control.</p><p>A <code>#N</code> link in the answer opens that event on <strong>Logs</strong>. If it is gone, a toast says <strong>The event is no longer in the logs</strong>.</p><p><strong>Try again</strong> on the last answer sends the same question once more. It is disabled while an answer is running or the chat is not ready.</p><p>If the chosen model fails in a way that is specific to that model, the answer offers <strong>Switch to Auto and try again</strong>. That selects <strong>Auto</strong> and sends the question again.</p><p>While a run waits for permission, the chat asks <strong>Allow the assistant to read logs?</strong>, <strong>… page code?</strong> or <strong>… the live page?</strong>. The choices are <strong>Allow</strong>, <strong>Allow in this chat</strong> and <strong>Deny</strong>. <strong>Allow in this chat</strong> lasts until <strong>New chat</strong>.</p><p>A failed answer shows the error in the card. <strong>Provider message</strong> expands the text returned by the provider.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ai/settings.html">Options → AI</a></li><li><a href="/qa-tools/docs/logs/general.html">Working with logs</a></li><li><a href="/qa-tools/docs/network/general.html">Working with requests</a></li><li><a href="/qa-tools/docs/props/general.html">Components and props</a></li><li><a href="/qa-tools/docs/store/general.html">Pinia stores</a></li></ul>',29)])])}const u=e(a,[["render",r]]);export{p as __pageData,u as default};
